/bin/bash -lc "unzip -Z1 inputs/scogs_fungi.zip | awk '
/\\.treefile"'$/ {tree++}
/'"\\.iqtree"'$/ {iq++}
/'"\\.log"'$/ {log++}
/'"\\.faa"'$/ {faa++}
/'"\\.faa\\.mafft"'$/ {mafft++}
/'"\\.faa\\.mafft\\.clipkit"'$/ {clip++}
END {print "treefile",tree+0; print "iqtree",iq+0; print "log",log+0; print "faa",faa+0; print "mafft",mafft+0; print "clipkit",clip+0}'"'"

