/bin/bash -lc "python3 - <<'PY'
import zipfile
z=zipfile.ZipFile('inputs/scogs_fungi.zip')
for term in ['treeness','Treeness','Sum of internal branch lengths']:
    c=0
    for n in z.namelist():
        if n.endswith(('.log','.iqtree')):
            if term in z.read(n).decode('utf-8','replace'):
                c+=1
    print(term, c)
PY"

